/**
 * `[2026-10-22 사용자 결정 — ST4F-717]` What the 「이용 방법」 screen (`/help`) says — the mockup `mockups/guguroute-help-center-2026-10-22.html`, read from the
 * code of that day. 「」 (English “ ”) hold the app's own words for a button or a screen; when a screen or a button name changes, change it here in the same work.
 * `needs`: hidden while the operator has that feature switched off (`GET /v1/web/features` — `lib/live/features.ts`).
 * `at`: where a numbered point sits on the screen's capture (780×1594, the intro's pictures — `features/intro/guide-steps.ts`).
 */
export type Pair = readonly [ko: string, en: string];
export type Switch = "guardian" | "riskPanel" | "planInputExtras";
export type ScreenId = "input" | "reading" | "check" | "result" | "trip" | "notices" | "chat" | "menu" | "settings" | "support";
export type FaqCategory = "register" | "trip" | "during" | "account" | "other";

export interface HelpPoint { at?: readonly [x: number, y: number]; label: Pair; desc: Pair; rule?: Pair; ruleNeeds?: Switch; needs?: Switch }
/** A row of the small board drawn for a screen that has no capture (menu · settings · inquiries); `point` is the number it carries. */
export interface BoardRow { title: Pair; note: Pair; point?: number }
export interface HelpScreen { id: ScreenId; name: Pair; where: Pair; note?: Pair; shot?: string; board?: readonly BoardRow[]; points: readonly HelpPoint[]; more?: readonly HelpPoint[] }
export interface Faq { id: string; category: FaqCategory; q: Pair; a: Pair; screens: readonly ScreenId[]; needs?: Switch }

