export const FAQ: readonly Faq[] = [
  { id: "scope", category: "register", screens: ["input", "check"], q: ["어떤 여행을 등록할 수 있나요?", "Which trips can I register?"],
    a: ["지금은 서울 여행, 최대 7일 · 4명까지예요. 계획에 범위를 넘는 내용(5명 이상, 8일 이상, 서울 밖 장소)이 있으면 막지 않고 계획 확인 화면에서 확인을 부탁드려요.", "Seoul trips for now, up to 7 days and 4 people. If the plan goes beyond that (5 or more people, 8 or more days, places outside Seoul), it is not refused — the plan check asks you to confirm."] },
  { id: "format", category: "register", screens: ["input"], q: ["계획은 어떤 형식으로 적어야 하나요?", "How should I write my plan?"],
    a: ["정해진 형식은 없어요. 일차 제목에 날짜를 적고(‘1일차 · 2026-10-29’), 그 아래에 시작 시간과 장소를 한 줄씩 적으면(‘09:00 경복궁’) 가장 잘 읽어요. 예약한 일정은 ‘예약 있음’으로 표시해 주세요. 「예시 불러오기」를 누르면 예시가 채워져요.", "Any way you like. It reads best with the date in each day’s heading (‘Day 1 · 2026-10-29’) and one line per stop with its start time and place (‘09:00 Gyeongbokgung’). Mark booked stops ‘booked’. “Load example” fills in an example."] },
  { id: "files", category: "register", screens: ["input", "reading"], needs: "planInputExtras", q: ["사진이나 파일로 된 계획도 올릴 수 있나요?", "Can I upload a photo or a file?"],
    a: ["「파일 선택」 칸에서 사진 · PDF · 워드 · 엑셀 · 텍스트 파일을 최대 5개, 한 개 10MB까지 올릴 수 있어요. 다시 고르면 앞의 선택에 더해지지 않고 바뀌니 한 번에 골라 주세요. 사진 한 장은 읽는 데 2분쯤 걸릴 수 있어요.", "In “Choose files”: photos, PDF, Word, Excel or text — up to 5, 10 MB each. Choosing again replaces the earlier choice, so pick them all at once. A photo can take about two minutes to read."] },
  { id: "which-box", category: "register", screens: ["input"], needs: "planInputExtras", q: ["세 칸에 모두 적으면 어느 것을 보내나요?", "I filled in more than one box. Which is sent?"],
    a: ["마지막에 누르거나 쓴 칸 하나만 보내요. 그 칸에 「보낼 칸」 표시가 붙어 있어요. 다른 칸에 적은 내용은 지워지지 않고 남아 있어요.", "Only the one you touched last — it is marked “Will be sent”. The others keep what you wrote."] },
  { id: "plan-for-me", category: "register", screens: ["input"], needs: "planInputExtras", q: ["일정을 대신 짜 주기도 하나요?", "Can you plan the trip for me?"],
    a: ["「계획 짜 주기 (테스트)」 칸에서 첫날 · 일수(1~7일) · 인원(1~4명)과 원하는 여행(선택, 500자까지)을 적으면 서울 일정을 짜 드려요. 짠 일정이 확인을 통과하면 중간 확인 화면 없이 바로 여행으로 등록돼요. 아직 시험 중인 기능이에요.", "In “Plan it for me (test)”, give the first day, days (1–7), people (1–4) and, if you like, what you want (up to 500 characters), and we plan a Seoul trip. Once it passes the check it is registered right away, without the check screen. Still being tried out."] },
  { id: "questions", category: "register", screens: ["reading"], q: ["읽는 동안 나오는 질문에 꼭 답해야 하나요?", "Do I have to answer the questions while you read?"],
    a: ["아니요. 답하지 않아도 계획 확인으로 넘어가요. 계획서에서 이미 읽은 것과 시작 설문에서 답한 것은 다시 묻지 않고, 남은 질문은 다음에 계획을 읽을 때 다시 답할 수 있어요.", "No — the plan check opens either way. We never ask what your plan or the survey already told us, and questions left can be answered the next time we read a plan."] },
  { id: "stopped", category: "register", screens: ["check"], q: ["확인 중에 멈췄어요. 어떻게 하나요?", "The check stopped. What now?"],
    a: ["쉬는 날이거나, 같은 이름의 장소가 여러 곳이거나, 이동이 일정보다 늦는 것처럼 고칠 곳이 있으면 그 일정에서 멈추고 선택지를 보여 드려요. 하나를 고르면 그 일정을 다시 확인하고 다음 일정으로 이어 가요. 맞는 선택지가 없으면 「직접 수정」이나 「삭제」를 눌러 주세요.", "When a stop needs a fix — a closed day, several places with the same name, travel arriving late — the check stops there with options. Pick one and that stop is checked again before the next. None fits? Press “Edit myself” or “Delete”."] },
  { id: "send-again", category: "register", screens: ["result"], q: ["고친 뒤에는 어떻게 다시 확인하나요?", "How is a change checked again?"],
    a: ["장소를 바꾸거나 지우면 오른쪽 아래 단추가 「다시 제출」로 바뀌어요. 누르면 앞뒤 이동까지 한 번에 다시 확인하고, 통과하면 단추가 「여행 등록」으로 바뀌어요. 이동 수단만 바꾼 경우는 그 구간만 바로 다시 계산해요.", "After changing or deleting a place, the round button becomes “Send again”. It checks the travel around it too and, once it passes, becomes “Register trip”. Changing only the travel mode works that leg out right away."] },
  { id: "recommend-all", category: "register", screens: ["result"], q: ["「전체 자동 추천」을 누르면 바로 바뀌나요?", "Does “Recommend all” change my plan at once?"],
    a: ["아니요. 저장하지 않고 수정안만 보여 줘요. 아래로 넘기면 권장 수정안, 위로 올리면 변경 전 일정이에요. 수정안을 보는 중에 「여행 등록」을 누르면 수정안을 저장한 뒤 등록해요.", "No — it only shows a proposal. Scroll down for the proposal, up for the plan as it was. Pressing “Register trip” while looking at the proposal saves it and registers."] },
  { id: "auto-register", category: "register", screens: ["result", "trip"], q: ["저절로 등록됐어요. 5초 막대는 무엇인가요?", "It registered by itself. What is the 5-second bar?"],
    a: ["모든 일정이 확인을 통과하면 「모두 확인했어요」 막대가 나오고 5초 뒤 여행을 등록해요. 더 살펴보려면 「자동으로 넘어가지 않기」를 누르거나 화면을 누르면 멈춰요. 등록한 뒤에도 여행 화면의 「일정 수정」으로 고칠 수 있어요.", "When every stop passes, the “All checked” bar registers the trip after 5 seconds. Press “Do not go on by itself”, or anywhere on the screen, to stop it. You can still change it later with “Edit itinerary”."] },
  { id: "keep-booked", category: "register", screens: ["result"], q: ["예약한 일정이 바뀌지 않게 하려면요?", "How do I keep a booked stop from changing?"],
    a: ["일정 카드의 자물쇠로 꼭 넣을 일정으로 고정해 두면 자동 추천과 자동 변경에서 빠지고, 바꿔야 할 때 먼저 물어봐요. 예약한 일정은 시간을 바꿀 수 없어요. 업체 예약 자체를 취소 · 변경하는 일은 구구루트가 하지 않으니 업체에서 따로 해 주세요.", "Lock it with the padlock on its card: it stays out of recommendations and automatic changes, and we ask before touching it. A booked stop’s time cannot change. GuguRoute does not cancel or change the booking itself — please do that with the business."] },
  { id: "draft", category: "register", screens: ["input"], q: ["등록 화면을 벗어나면 적던 계획이 사라지나요?", "Do I lose my draft if I leave the plan screen?"],
    a: ["같은 탭에서는 화면을 오가도 남아 있어요. 탭을 닫으면 사라질 수 있고, 여행으로 등록하면 비워져요.", "Not in the same tab. Closing the tab may lose it, and it is cleared once the trip is registered."] },
  { id: "find-trip", category: "trip", screens: ["menu", "trip"], q: ["등록한 여행은 어디서 다시 보나요?", "Where do I find my trips again?"],
    a: ["메뉴 › 「여행 목록 보기」에서 열어요. 최근에 등록한 여행이 위에 있어요. 게스트로 만든 여행은 창을 닫으면 이어 볼 수 없고, 계정에 보관한 여행은 로그인하면 다시 열려요.", "Menu › “View trip list”, newest first. A guest trip cannot be opened again once the window is closed; trips kept in your account open again when you sign in."] },
  { id: "edit-after", category: "trip", screens: ["trip", "notices"], q: ["등록한 뒤에도 일정을 고칠 수 있나요?", "Can I change the trip after registering?"],
    a: ["네. 여행 화면의 「일정 수정」(✎)을 누르면 같은 화면이 수정 모드가 돼요. 끝난 일정은 그대로 두고, 진행 중인 일정과 남은 일정을 고칠 수 있어요. 고친 뒤 「다시 제출」로 확인하고 「완료」를 누르면 여행의 새 판으로 저장되고 알림 센터 「소식」에 남아요.", "Yes. “Edit itinerary” (✎) on the trip screen opens edit mode. Finished stops stay; the current and remaining ones can change. Check with “Send again”, press “Done”, and it is saved as a new version, listed under “Updates” in the notice center."] },
  { id: "cannot-edit", category: "trip", screens: ["trip"], q: ["수정 모드에서 바꿀 수 없는 일정이 있어요.", "Some stops cannot be changed in edit mode."],
    a: ["끝난 일정, 자정을 넘는 일정, 위치를 모르는 장소는 수정 모드에서 바꿀 수 없어요. 숙소 · 항공 · 예약한 일정은 잠긴 채로 들어오고, 잠금을 풀어야 고칠 수 있어요. 여행 이름 · 인원 · 첫날은 바꿀 수 없어요.", "Finished stops, stops past midnight and places with no known location cannot change there. Stays, flights and booked stops come in locked — unlock them first. The trip name, number of people and first day cannot change."] },
  { id: "chat", category: "trip", screens: ["chat"], q: ["채팅으로 무엇을 할 수 있나요?", "What can I do in chat?"],
    a: ["일정에 대해 묻거나(‘오늘 일정 알려줘’) 바꿔 달라고 말할 수 있어요(‘점심 식당 다른 곳으로 바꿔줘’, ‘30분 늦어요’). 채팅으로 바꾸면 여행계획서에 새 판이 생기고, 마음에 들지 않으면 「되돌리기」로 되돌려요. 숙소 · 항공 · 예약한 일정은 채팅으로 바꾸지 않아요.", "Ask about your trip (‘what’s on today’) or ask for changes (‘change the lunch place’, ‘I’m 30 minutes late’). A change in chat makes a new version of your trip plan; “Undo” takes it back. Stays, flights and booked stops are not changed by chat."] },
  { id: "plan-link", category: "trip", screens: ["trip"], q: ["여행계획서 링크는 무엇이고 어떻게 나누나요?", "What is the trip plan link and how do I share it?"],
    a: ["로그인 없이 열리는 내 여행 페이지예요. 여행 이름을 누르면 「여행계획서 열기」 · 「공유하기」가 나와요. 「링크 복사」나 메시지 · 텔레그램 등으로 보내고, 「파일로 내려받기」로 파일을 저장할 수도 있어요. 링크를 아는 사람은 누구나 볼 수 있으니 주의해 주세요.", "A page of your trip that opens without signing in. Press the trip name for “Open your trip plan” and “Share”: “Copy link”, messages, Telegram and more, or “Download as a file”. Anyone with the link can see it, so share it with care."] },
  { id: "map-apps", category: "trip", screens: ["trip"], q: ["지도 앱으로 길을 보고 싶어요.", "Can I see the way in a maps app?"],
    a: ["일정 카드를 펼쳐 「지도 앱으로 열기」를 누르면 네이버 지도 · 카카오맵 · 구글 지도 중에서 골라 열어요. 이동 줄을 펼치면 「지도 앱에서 길찾기」가 있어요.", "Open a stop’s card and press “Open in a maps app” for Naver Map, KakaoMap or Google Maps. A travel line has “Directions in a maps app”."] },
  { id: "location", category: "trip", screens: ["trip", "settings"], q: ["지도에 내 위치가 보이지 않아요.", "My location is not on the map."],
    a: ["지도 단추의 내 위치로를 누르면 위치 이용 동의(선택)를 먼저 물어요. 동의하면 지도에 내 위치가 보이고, 여행 화면이 열려 있는 동안 위치를 서버로 보내 머문 곳을 지도에 그려요. 「약관 · 동의」에서 철회하면 더 보내지 않고 서버의 위치 기록도 지워요.", "The map’s my-location button first asks for the (optional) location agreement. Then your location shows, and while the trip screen is open it is sent to the server to draw where you stayed. Withdrawing it in “Terms & consents” stops that and deletes the server’s location record."] },
  { id: "past", category: "trip", screens: ["trip"], q: ["지난 일정이 회색 한 줄로 바뀌었어요.", "Past stops turned into grey lines."],
    a: ["끝 시각이 지난 일정은 접혀서 회색 한 줄로 보여요. 누르면 다시 펼쳐져요. 오늘 줄에는 지금 시각이 점으로 찍혀요.", "A stop whose end time has passed folds into a grey line; press to open it. Today’s line has a dot at the current time."] },
  { id: "delete-trip", category: "trip", screens: ["menu"], q: ["여행을 지우고 싶어요.", "How do I delete a trip?"],
    a: ["「여행 목록」에서 줄의 휴지통이나 「선택 삭제」로 지워요. 여행과 채팅 기록, 여행계획서 링크가 지워지고 알림도 멈춰요. 지운 여행은 되돌릴 수 없어요.", "In the “Trip list”, use the bin on its line or “Select to delete”. The trip, its chat and the trip plan link are deleted and alerts stop. It cannot be undone."] },
  { id: "trip-over", category: "trip", screens: ["trip"], q: ["여행이 끝나면 어떻게 되나요?", "What happens when the trip ends?"],
    a: ["마지막 일정이 끝나면 「전체」 맨 위에 「여행이 끝났어요」 카드가 나오고 「엔딩 크레딧 보기」로 여행을 돌아볼 수 있어요. 끝 화면의 「공유하기」는 세로 사진 한 장으로 나눠요.", "When the last stop ends, “The trip is over” appears at the top of “All” with “Watch the end credits”. “Share” at the end shares it as one portrait picture."] },
  { id: "keeper", category: "during", screens: ["reading", "notices"], needs: "guardian", q: ["항로 지킴이는 무엇인가요?", "What is the Course Keeper?"],
    a: ["여행 중 휴무 · 날씨 · 재난 같은 문제가 생겼을 때 일정을 돌보는 기능이에요. 켜 두면 문제가 생길 때 알아서 바꾸고 알려 드려요(되돌릴 수 있어요). 끄면 바꾸기 전에 먼저 물어봐요. 켜 두어도 고정한 일정은 먼저 물어봐요.", "It looks after your trip when a place closes, the weather turns or a disaster hits. When on, it changes the plan and tells you (you can undo it). When off, it asks first. Locked stops are always asked about first."] },
  { id: "keeper-switch", category: "during", screens: ["reading", "trip"], needs: "guardian", q: ["항로 지킴이는 어디서 켜고 끄나요?", "Where do I turn the Course Keeper on or off?"],
    a: ["처음 「계획 확인하기」를 누르면 뜨는 카드에서 고르고, 계획 확인 중에는 화면 위 방패 아이콘, 등록한 여행에서는 메뉴를 열었을 때 머리의 방패 아이콘에서 바꿔요. 끄면 「되돌리기」가 함께 떠요.", "Choose on the card after your first “Check my plan”; during the check, use the shield icon at the top; on a registered trip, the shield at the top of the menu. Turning it off shows “Undo”."] },
  { id: "disaster", category: "during", screens: ["notices", "trip"], q: ["재난이 나면 어떻게 되나요?", "What happens if a disaster hits?"],
    a: ["재난이나 지진이 나면 일정을 멈추고, 가까운 대피 장소와 안전 안내를 보내요. 여행 화면에 「일정 정지 중」이 뜨고 저절로 풀리지 않아요. 안전한 곳에 있는 것을 확인한 뒤 「일정 다시 시작」을 눌러 주세요.", "Your trip is paused and we send the nearest shelter and safety guidance. The trip screen shows “Itinerary paused” and it does not resume by itself — press “Resume the itinerary” once you are safe."] },
  { id: "choice", category: "during", screens: ["notices", "trip"], q: ["「선택이 필요해요」가 떴어요. 꼭 골라야 하나요?", "I got “Needs your choice”. Do I have to choose?"],
    a: ["여행 중 바꿀 만한 일이 생기면 대안을 보여 드리고 고르게 해요. 대안을 고르면 그 일정을 바꾸고, 「지금 일정 그대로 두기」를 누르거나 답하지 않으면 원래 일정을 그대로 둬요. 알림 센터의 「할 일」, 그 일정의 「상세 보기」, 채팅에서 답할 수 있어요. 새 알림 막대의 「상세 보기」를 누르면 바로 그 일정의 상세 보기로 가요.", "When something is worth changing, we show alternatives. Pick one and the stop changes; “Keep the current plan”, or no answer, keeps it. Answer under “To do” in the notice center, in the stop’s “Details” or in chat — “Details” on the new-notice bar takes you straight to the stop."] },
  { id: "risk-panel", category: "during", screens: ["notices"], needs: "riskPanel", q: ["「현재 일정 위험 확인」은 무엇인가요?", "What is “Current itinerary risks”?"],
    a: ["가까운 일정에 날씨 · 재난 위험이 겹치는지 확인해 보여 주는 칸이에요. 겹치면 그 일정을 알려 주고, 「실내 대안 보기」로 대안을 찾아볼 수 있어요. 「다시 확인」을 누르면 지금 다시 확인해요. 확인하지 못해도 「현재 일정은 유지돼요. 다시 확인해 주세요.」라고 알려 드려요.", "A panel that checks the coming stops for weather and disaster risks. If one is hit, it names the stop and “See indoor alternatives” looks for others. “Check again” checks now. If it cannot check, it says “Your itinerary is kept. Check again.”"] },
  { id: "alerts-where", category: "during", screens: ["settings"], q: ["알림은 어디로 받나요?", "Where do alerts arrive?"],
    a: ["로그인한 뒤 설정 › 「알림 받는 곳」에서 디스코드를(서버가 지원하면 텔레그램도) 연결해요. 연결한 뒤 「시험 메시지 보내기」로 확인해 보세요. 알림은 한 번에 한 곳으로 보내고, 알림 채널 정보 동의가 필요해요. 게스트는 일정 알림을 받지 않아요.", "Sign in, then connect Discord (and Telegram when the server offers it) in Settings › “Where alerts go”, and try “Send a test message”. Alerts go to one place at a time and need the alert channel agreement. Guests do not get trip alerts."] },
  { id: "alerts-what", category: "during", screens: ["notices"], q: ["알림에는 무엇이 오나요?", "What is in an alert?"],
    a: ["바뀐 일정의 장소 이름과 시각, 여행계획서 링크가 와요. 알림은 승인 요청이 아니에요 — 최신 일정은 여행 화면과 여행계획서에서 확인해 주세요. 앱 안에서는 알림 센터의 「소식」에 최근 10개가 보여요.", "The changed stop’s place and time, and your trip plan link. An alert is not a request for approval — the trip screen and the trip plan always show the latest. In the app, “Updates” in the notice center shows the last 10."] },
  { id: "browser-alerts", category: "during", screens: ["notices"], q: ["휴대폰 알림으로도 받을 수 있나요?", "Can I get alerts on my phone?"],
    a: ["「소식」 탭의 「브라우저 알림 켜기」를 누르면, 여행 화면 탭이 열려 있는 동안 기기 알림으로도 받아요. 탭을 닫으면 오지 않으니, 바깥에서도 받으려면 디스코드나 텔레그램을 연결해 주세요.", "“Turn on browser notifications” under Updates alerts your device while the trip tab is open. Closed tabs get nothing, so connect Discord or Telegram for alerts anywhere."] },
  { id: "guest", category: "account", screens: ["menu", "settings"], q: ["로그인하지 않고 써도 되나요?", "Can I use it without signing in?"],
    a: ["네, 게스트로 쓸 수 있어요. 다만 여행은 1개까지(오늘부터 1년 안에 시작, 7일 이내)이고 일정 알림을 받지 않아요. 창을 닫으면 이어 쓸 수 없고, 서버 자료는 마지막 이용 후 7일 뒤 지워져요. 로그인하면 이 제한이 없어지고 지금 만든 여행도 계정에 담겨요.", "Yes, as a guest — with one trip (starting within a year, up to 7 days) and no trip alerts. Closing the window ends it, and the server deletes your data 7 days after you last used it. Signing in lifts these limits and keeps the trip you made."] },
  { id: "sign-in", category: "account", screens: ["settings"], q: ["어떤 계정으로 로그인하나요?", "Which accounts can I sign in with?"],
    a: ["구글 · 카카오 · 네이버 · 디스코드 중 서비스에서 켜 둔 방법으로 로그인해요. 이메일 · 비밀번호 가입은 없어요. 처음이면 필수 약관에 동의한 뒤 계정이 만들어져요.", "Whichever of Google, Kakao, Naver and Discord the service has on. There is no email-and-password sign-up. The first time, your account is made once you agree to the required terms."] },
  { id: "sign-out", category: "account", screens: ["settings"], q: ["로그아웃은 어디서 하나요?", "Where do I sign out?"],
    a: ["설정 › 「로그인 · 계정」의 「로그아웃」에서 해요. 로그아웃해도 계정의 여행은 그대로 있고, 다시 로그인하면 열 수 있어요. 이 브라우저에 있던 동의 기록과 설문 답은 함께 지워져요.", "Settings › “Sign-in & accounts” › “Sign out”. Your account’s trips stay and open again when you sign in. This browser’s consent copy and survey answers are cleared."] },
  { id: "retention", category: "account", screens: [], q: ["내 자료는 얼마나 보관되나요?", "How long is my data kept?"],
    a: ["게스트 자료는 마지막 이용 후 7일이에요(끝나지 않은 일정이 있으면 그 일정이 끝난 뒤 3일까지). 회원 자료는 지우거나 탈퇴를 요청할 때까지 두되, 마지막 이용 후 1년이 지나면 파기해요. 위치 기록은 여행이 끝난 뒤 7일 보관해요.", "Guest data: 7 days after you last used it (up to 3 days after an unfinished trip ends). Member data: until you delete it or ask to leave, and at most a year after you last used it. Location records: 7 days after the trip ends."] },
  { id: "leave", category: "account", screens: ["settings"], q: ["계정을 지우고 싶어요.", "I want to delete my account."],
    a: ["아직 화면에 탈퇴 단추는 없어요. 여행 삭제, 계정 연결 풀기, 선택 동의 철회는 화면에서 바로 할 수 있고, 회원 자료 전체 삭제는 문의처(acopilot3206@gmail.com)로 요청해 주세요.", "There is no button for it yet. Deleting trips, disconnecting accounts and withdrawing optional agreements are on the screens; to delete all member data, write to acopilot3206@gmail.com."] },
  { id: "optional-terms", category: "account", screens: ["settings"], q: ["선택 약관에 꼭 동의해야 하나요?", "Must I agree to the optional terms?"],
    a: ["아니요. 필수 두 가지(서비스 이용약관 · 개인정보)만 동의하면 쓸 수 있어요. 위치 · 알림 채널 · 민감정보 · 서비스 개선은 선택이고, 설정 › 「약관 · 동의」에서 언제든 철회할 수 있어요. 철회하면 그 기능의 자료(위치 기록, 연결한 알림 등)를 함께 지우거나 풀어요.", "No — the two required ones (terms of service, personal data) are enough. Location, alert channel, sensitive data and service improvement are optional and can be withdrawn any time in Settings › “Terms & consents”; withdrawing deletes or disconnects that feature’s data."] },
  { id: "language", category: "account", screens: ["settings", "input"], q: ["언어나 화면 색을 바꾸고 싶어요.", "How do I change the language or colours?"],
    a: ["설정에서 언어(한국어 · English)와 테마(「기기 설정 따르기」 · 「그린」 · 「다크」)를 골라요. 약관 동의 전에는 화면 위 지구본 단추로 언어를 바꿔요. 서버가 보낸 문장은 자동으로 번역되지 않아요.", "In Settings: language (한국어 · English) and theme (“Match device”, “Green”, “Dark”). Before agreeing to the terms, use the globe at the top. Sentences from the server are not translated."] },
  { id: "profile", category: "account", screens: ["menu"], q: ["닉네임이나 프로필 사진을 바꿀 수 있나요?", "Can I change my nickname or picture?"],
    a: ["아직 준비 중이에요. 「프로필 수정」 화면에 칸은 있지만 저장되지 않아요.", "Not yet — “Edit profile” has the boxes, but they are not saved."] },
  { id: "booking", category: "other", screens: [], q: ["예약이나 결제도 해 주나요?", "Do you book or pay for things?"],
    a: ["아니요. 일정을 확인하고 지켜보는 서비스라 업체 예약 · 결제 · 취소는 하지 않아요. 택시도 예상 요금만 보여 드리고 배차 · 결제는 하지 않아요.", "No. We check and watch your plan; we do not book, pay or cancel with businesses. For taxis we only show an estimated fare — no dispatch, no payment."] },
  { id: "inquiry", category: "other", screens: ["support"], q: ["문의는 어떻게 하고, 답변은 어디서 보나요?", "How do I ask a question, and where is the answer?"],
    a: ["메뉴 › 「문의함」 › 「문의 작성」에서 제목과 내용을 적어 보내요. 답변이 달리면 「내 문의」에서 그 문의가 「답변 완료」가 되고, 눌러서 볼 수 있어요. 운영자는 답변만 하고 일정을 대신 고치지 않아요.", "Menu › “Inquiries” › “Write an inquiry”. Once answered, it shows “Answered” in “My inquiries” — open it to read. The team answers but does not change your trip for you."] },
  { id: "outage", category: "other", screens: ["support", "notices"], q: ["점검이나 장애 소식은 어디서 보나요?", "Where do I see maintenance or outage news?"],
    a: ["화면 맨 위 공지 배너와 메뉴 › 「공지사항」에서 봐요. 여행 화면에서는 알림 센터의 「공지」 탭에도 나와요.", "In the banner at the top and Menu › “Notices”. On the trip screen, also under “Notice” in the notice center."] },
  { id: "agent", category: "other", screens: ["settings"], q: ["개인 AI(클로드 등)에서 내 여행을 볼 수 있나요?", "Can my personal AI (Claude, for example) see my trip?"],
    a: ["로그인한 뒤 설정 › 「에이전트 연결」에서 키를 만들면 돼요. 「읽기만 (추천)」 · 「읽기·쓰기」 권한과 7 · 30 · 90일 유효 기간을 고르고, 키는 만들 때 한 번만 보여요. 쓰기 키라도 서비스의 쓰기 스위치가 꺼져 있으면 읽기만 돼요. 쓰지 않는 키는 「폐기」해 주세요.", "Sign in and make a key in Settings › “Connect an agent”: “Read only (recommended)” or “Read & write”, valid 7, 30 or 90 days. The key is shown once. Even a write key only reads while the service’s write switch is off. “Revoke” keys you no longer use."] },
  { id: "motion", category: "other", screens: ["settings"], q: ["화면 움직임이 너무 많아요.", "There is too much movement on screen."],
    a: ["설정의 「애니메이션 건너뛰기」를 켜면 계획 확인 화면이 단계별 재생 없이 바로 떠요. 일정 목록 글자는 「일정 목록 크기」(80~130%)에서 키우거나 줄여요.", "Turn on “Skip animations” in Settings and the plan check shows at once. “Schedule list size” (80–130%) changes the list text."] },
];
